// Mini sistema de reactividad con Proxy.
const suscriptores = new WeakMap();   // objeto -> (propiedad -> conjunto de efectos)
let efectoActivo = null;

function efecto(fn) {
  const correr = () => { efectoActivo = correr; fn(); efectoActivo = null; };
  correr();
}

function reactivo(obj) {
  return new Proxy(obj, {
    get(o, clave) {
      if (efectoActivo) {                       // alguien está leyendo: anotarlo
        if (!suscriptores.has(o)) suscriptores.set(o, new Map());
        const mapa = suscriptores.get(o);
        if (!mapa.has(clave)) mapa.set(clave, new Set());
        mapa.get(clave).add(efectoActivo);
      }
      return o[clave];
    },
    set(o, clave, valor) {
      if (o[clave] === valor) return true;      // sin cambio real, nadie se entera
      o[clave] = valor;
      const efectos = suscriptores.get(o)?.get(clave);
      if (efectos) [...efectos].forEach((e) => e());   // avisar a los que la leyeron
      return true;
    },
  });
}

const envio = reactivo({ bultos: 12, cliente: "Ferretería Norte", estado: "en ruta" });
let corridasA = 0, corridasB = 0;

efecto(() => { corridasA++; console.log("A lee bultos:", envio.bultos); });
efecto(() => { corridasB++; console.log("B lee cliente y estado:", envio.cliente, envio.estado); });

console.log("--- cambio bultos");
envio.bultos = 15;
console.log("--- cambio estado");
envio.estado = "entregado";
console.log("--- cambio bultos al mismo valor");
envio.bultos = 15;
console.log(`corridas: A=${corridasA}, B=${corridasB}`);

